mapper.delete:
DELETE FROM
	photo.portfolio_photo


	 AND 1 = 0
	 AND account_no = #{accountNo}
	 AND portfolio_no = #{portfolioNo}
	 AND photo_no = #{photoNo}

mapper.select:
SELECT pp.account_no, pp.portfolio_no, pp.photo_no, pp.display_order, pp.photo_settings, pm.photo_japanese_title, pm.image_file_path, pm.direction_kbn FROM photo.portfolio_photo pp INNER JOIN photo.photo_mst pm ON pm.account_no = pp.account_no AND pm.photo_no = pp.photo_no
AND pp.account_no = #{accountNo} AND pp.portfolio_no = #{portfolioNo} AND pp.photo_no = #{photoNo}
ORDER BY pp.portfolio_no, pp.display_order

SELECT ph.photo_no, ph.photo_japanese_title, ph.image_file_path, ph.direction_kbn FROM photo.photo_mst ph WHERE ph.account_no = #{accountNo} AND ph.is_deleted = false
AND ( ph.photo_japanese_title ILIKE #{keywordPattern} ESCAPE '\' OR ph.photo_english_title ILIKE #{keywordPattern} ESCAPE '\' OR EXISTS ( SELECT 1 FROM common.location_mst lm WHERE lm.account_no = ph.account_no AND lm.location_no = ph.location_no AND lm.is_deleted = false AND ( lm.display_name ILIKE #{keywordPattern} ESCAPE '\' OR lm.management_name ILIKE #{keywordPattern} ESCAPE '\' OR lm.address ILIKE #{keywordPattern} ESCAPE '\' ) ) OR EXISTS ( SELECT 1 FROM photo.photo_tag_mst ptm WHERE ptm.account_no = ph.account_no AND ptm.photo_no = ph.photo_no AND ( ptm.tag_japanese_name ILIKE #{keywordPattern} ESCAPE '\' OR ptm.tag_english_name ILIKE #{keywordPattern} ESCAPE '\' ) ) )
ORDER BY ph.photo_no DESC LIMIT #{limit} OFFSET #{offset}
